"use client";
import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { useParams, useRouter } from 'next/navigation';
import Sidebar from "../../../components/sidebar"; // Importation de Sidebar
import Navbar from "../../../components/Navbar";

export default function Edituser() {
  const [inputs, setInputs] = useState({
    titre: ""
  });
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState(null);
  const { id } = useParams();
  const router = useRouter();

  useEffect(() => {
    if (id) {
      getUser();
    } else {
      setError("L'identifiant du sujet est manquant");
      setIsLoading(false);
    }
  }, [id]);

  function getUser() {
    axios.get(`http://localhost:5000/api/getsujet/${id}`)
      .then(function(response) {
        const userData = response.data; // Utilisez response.data directement
        setInputs({
          titre: userData.titre
        });
        setIsLoading(false);
      })
      .catch(err => {
        console.error("Erreur lors de la récupération du sujet:", err);
        setError("Erreur lors de la récupération des données du sujet.");
        setIsLoading(false);
      });
  }

  const handleChange = (event) => {
    const { name, value } = event.target;
    setInputs(prevValues => ({ ...prevValues, [name]: value }));
  }

  const handleSubmit = (event) => {
    event.preventDefault();
    axios.put(`http://localhost:5000/api/editsujet/${id}`, inputs)
      .then(function(response) {
        router.push('/users/readSuj'); // Redirige vers la page d'accueil après la mise à jour
      })
      .catch(err => {
        console.error("Erreur lors de la mise à jour du sujet:", err);
        setError("Erreur lors de la mise à jour du sujet.");
      });
  }

  if (isLoading) {
    return <div>Loading...</div>;
  }

  return (
    <div className="flex h-screen w-screen">
      {/* Sidebar */}
      <Sidebar className="h-screen" />
      <div className="w-full flex flex-col h-screen">
        {/* Navbar */}
        <Navbar />
        <div className="w-full flex-1 py-5 flex flex-col items-center overflow-hidden">
          <div className="max-w-md mx-auto mt-5">
            <button
              onClick={() => router.push("/users/readSuj")}
              className="mb-5 flex items-center text-blue-600 hover:text-blue-800 transition"
            >
              ← Retour à la gestion des sujets
            </button>
            <h1 className="text-2xl text-center mb-2">Modifier le sujet</h1>
            {error && <p className="text-red-500 text-center">{error}</p>}
            <form onSubmit={handleSubmit}>
              <div className="mb-5">
                <label htmlFor="titre" className="block text-sm font-medium text-gray-900">Nom du sujet</label>
                <input
                  type="text"
                  name="titre"
                  id="titre"
                  value={inputs.titre || ''}
                  className="w-full px-4 py-2 mt-2 border border-blue-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none shadow-sm transition"
                  placeholder="Nom du sujet..."
                  onChange={handleChange}
                />
              </div>
              <button
                type="submit"
                className="bg-blue-500 text-white w-full py-2 px-5 rounded-lg shadow-md hover:bg-blue-600"
              >
                Modifier
              </button>
            </form>
          </div>
        </div>
      </div>
    </div>
  );
}